%[text]{"align":"center"} # **Lab 1: Feedback principles**
%[text]{"align":"center"} 
%[text]{"align":"center"} **yongcui.mi@hv.se**
%[text] ## 1. Introduction
%[text] Feedback is a fundamental concept in control systems. It enables a system to:
%[text] - track reference signals,
%[text] - reduce the effect of disturbances,
%[text] - and simplify the behavior of nonlinear systems.  \
%[text] Nonlinear systems are often difficult to analyze and control due to their complex and unpredictable behavior. However, by applying feedback, it is possible to approximate their behavior with linear models, especially around an operating point.
%[text] This lab focuses on understanding how **negative feedback can be used to linearize nonlinear systems**.
%[text] Before working on the main tasks (Section 3), Section 2 introduces basic MATLAB commands for system modeling and analysis.
%[text] **Requirement:**
%[text] To pass the lab, results must be presented to the lab assistant during lab time.
%[text] ## 2. Basic functions
%[text] ### 2. 1 Create transfer functions using command *tf().*
%%
%[text] Creat transfer function in matlab for $G\\left(s\\right)=\\frac{s+1}{s^2 +5s+6}${"editStyle":"visual"}. 
%%Specify the numerator and denominator coefficients ordered in descending powers of s
numerator = [1,1];
denominator = [1,5,6];
G= tf(numerator,denominator);
%%
%[text] #### Or 
%% Specify s as a tf object.
s = tf('s');
G = (s + 1)/(s^2 + 5*s + 6);
%%\
%%
%[text] 
%[text] ### 2. 2 Generate response of a transfer function using command *step(), lsim().*
%[text] Generate step response of the transfer function $G\\left(s\\right)=\\frac{s+1}{s^2 +5s+6}${"editStyle":"visual"}
y = step(G);
%%Specify the the simulation time interval explicitly
T=0:0.01:10;
ys = step(G, T);
%%\
%%
%[text] 
%[text] The response to a specific input signal can be generated 
u=sin(5*T);
yu = lsim(G, u, T);%%u and t are the input and time vectors.%%
%%
%[text] 
%[text] ### 2.3 Plot 
figure %[output:427652d6]
plot(T,ys) %[output:427652d6]
hold on %[output:427652d6]
plot(T,yu) %[output:427652d6]
grid on; %[output:427652d6]
subplot(2,1,1) %[output:8fb22c10]
plot(T,ys) %[output:8fb22c10]
subplot(2,1,2) %[output:8fb22c10]
plot(T,yu) %[output:8fb22c10]
title('system response') %[output:8fb22c10]
legend('data1') %[output:8fb22c10]
%%
%[text] ## 3. Tasks
%[text] 
%[text] ### 3.1  Linear behavior via feedback
%[text] Consider an open-loop system with the nonlinear input/output relation $y = F(u)$.
%[text] Assume that the system is closed with the proportional controller $u = k(r-y)$.
%[text] Show that the input/output relation of the closed-loop system is
%[text] $y + \\frac{1}{k}F^{-1}(y) = r$
%[text] Estimate the largest deviation from the ideal linear response $y=r$.  
%[text] Illustrate by plotting the input-output responses for
%[text] a) $F(u)=\\sqrt{u}$
%[text] b) $F(u)=u^2$
%[text] with $0 \\leq u \\leq 1$ and $k=5,\\ 10,\\ 100$.
%[text] 
%[text] A block diagram of the system with a simple propotional  controller is shown in Figure 1.
%[text] ![](text:image:35d2)
%[text] Fig. 1
r=0:0.01:1;

%[text] When $F(u)=\\sqrt{u}$; 
%[text] Plot the original input-output response:
figure %[output:02dce55c]
plot(r,r.^0.5,'b--.') %[output:02dce55c]
hold on %[output:02dce55c]
%[text] Plot the ideal input-output response:
plot(r,r,'g--') %[output:02dce55c]
hold on %[output:02dce55c]
%%
%[text] Plot the input-ouput response when proportional controller is used with k=5,10 and 100.
%[text] The key is to find the relation between r and y of the closed loop.
r = 0:0.01:1;
figure; %[output:691b4180]
plot(r, r.^0.5, 'b--.');   % open loop %[output:691b4180]
hold on; %[output:691b4180]
plot(r, r, 'g--');           % ideal %[output:691b4180]
for k = [5 10 100]
    y = (-k + sqrt(k^2 + 4*k*r)) / 2;
    plot(r, y); %[output:691b4180]
    hold on;
end
hold off; %[output:691b4180]
title('F(u)=sqrt(u): effect of feedback gain k'); %[output:691b4180]
legend('Open loop','Ideal','k=5','k=10','k=100'); %[output:691b4180]
%%
%[text] When $F(u)=u^2$, find the relation between r and y of the closed loop and plot the input-output response for : original, ideal and closed loop with negative feeaback k=5,10 and 100.
%%Implement it yourself 
r = 0:0.01:1;
figure; %[output:29fb9f60]
plot(r, r.^2, 'b--.');     % open loop %[output:29fb9f60]
hold on; %[output:29fb9f60]
plot(r, r, 'g--');          % ideal %[output:29fb9f60]
for k = [5 10 100]
    t = (-1/k + sqrt(1/k^2 + 4*r)) / 2;
    y = t.^2;
    plot(r, y); %[output:29fb9f60]
    hold on;
end
hold off; %[output:29fb9f60]
title('F(u)=u^2: effect of feedback gain k'); %[output:29fb9f60]
legend('Open loop','Ideal','k=5','k=10','k=100'); %[output:29fb9f60]
%%
%[text] ## 3.2
%[text] 
%[text] Write a MATLAB function that implements a nonlinear amplifier with static gain
%[text] $y = 2\\left(z + a z (1 - z) - 0.5 \\right), \\quad z = \\frac{x + 1}{2}$
%[text] where $x$ is the original signal (assumed to take values between $-1$ and $1$), and $a$ is the amplifier gain.
%[text] Compare the sound obtained when:
%[text] \- The music is sent through two amplifiers with gain $a = 1$
%[text] \- The music is sent through the same two amplifiers with feedback $k = 10$
%%
%[text] 
load handel % Load Handel’s Messiah
sound(y, Fs); pause % Play the original music through speaker

x = y;                          % original audio signal

% First amplifier
z1 = (x + 1)./2;
a = 1;
y1 = 2*(z1 + a.*z1.*(1-z1) - 0.5);

% Second amplifier (feed output of first into second)
z2 = (y1 + 1)./2;
y2 = 2*(z2 + a.*z2.*(1-z2) - 0.5);

sound(y2, Fs);   % play distorted result
%%
%[text] When the signal pass trhough one amplifiers with given nonlinearity and gain a=1;
x=y;
z=(x+1)./2;
a=1;
y_filtered=2*(z+a.*z.*(1-z)-0.5);
%%
%play the sound after one nonlinear amplifier
sound(y_filtered, Fs);
%%
%[text] Calculate the signal that is passed through two nonlinear applifiers with given  nonlinearity and gain a=1;
%%Implement it yourself
load handel
k = 10; a = 1;
r_signal = y;   % original audio
y_fb = zeros(size(r_signal));

for i = 1:length(r_signal)
    r_i = r_signal(i);
    % Solve: y + (1/k)*(1 - sqrt(2-2*y)) = r_i for y
    fun = @(yv) yv + (1/k)*(1 - sqrt(max(0, 2-2*yv))) - r_i;
    y_fb(i) = fzero(fun, r_i);
end

sound(y_fb, Fs);  % play feedback-corrected result
%[text] For nonlinear applifier with feedback gain k=10, a=1: 
%[text] First, find open loop nonlinear equation y=F(u)
syms u z
% z=;
% y=;
%pretty(y)
%%subs(y,u,2)
%%The nonlinear equation is: y=(2*u-u^2+1)/2

syms u z
z = (u + 1)/2;
a = 1;
y = 2*(z + a*z*(1-z) - 0.5);
y = simplify(y)     % → (2*u - u^2 + 1)/2 %[output:491eba57]
pretty(y) %[output:2dcbbca1]
%%
%[text] For the closed loop, it will have block diagram like that is shown in Fig,1. Find the relation between r and y: 
%%
%%You may need symbolic calculation

syms u y_sym z

% Define the amplifier
z = (u + 1)/2;
a = 1;
F = 2*(z + a*z*(1-z) - 0.5);
F = simplify(F)        % → (2*u - u^2 + 1)/2 %[output:00260550]
pretty(F) %[output:32c9869a]

% Invert: solve F(u) = y for u
F_inv = solve(F == y_sym, u);
F_inv = simplify(F_inv)   % gives two roots; pick 1 - sqrt(2 - 2*y) %[output:8039f9e2]

% Closed-loop relation
k = 10;
r_expr = y_sym + (1/k) * F_inv(1);  % pick the valid root
pretty(r_expr) %[output:88115060]

